// One atomic edit: an insertion or a deletion at a position, anchored to a revision.
class Operation {
    enum Type { INSERT, DELETE }

    private final Type type;              // insert or delete
    private final int position;             // where in the document this applies
    private final String text;                // the inserted text, or the text being deleted
    private final int baseRevision;              // the revision this operation was generated against

    public Operation(Type type, int position, String text, int baseRevision) {
        this.type = type;                 // store the operation kind
        this.position = position;           // store the target position
        this.text = text;                     // store the text payload
        this.baseRevision = baseRevision;       // store which revision this was generated against
    }

    public Type getType() { return type; }                     // type getter
    public int getPosition() { return position; }                 // position getter
    public String getText() { return text; }                        // text getter
    public int getBaseRevision() { return baseRevision; }               // base revision getter
}

// Transforms one operation against another that was already committed first,
// so applying the transformed operation on top of the already-updated document
// produces the same final result every client will converge on.
class OperationalTransform {

    // Transforms incoming (not yet applied) against already (already committed).
    public static Operation transform(Operation incoming, Operation already) {
        if (incoming.getType() == Operation.Type.INSERT && already.getType() == Operation.Type.INSERT) {
            return transformInsertInsert(incoming, already); // both are inserts
        }
        if (incoming.getType() == Operation.Type.INSERT && already.getType() == Operation.Type.DELETE) {
            return transformInsertDelete(incoming, already); // incoming inserts, already deleted
        }
        if (incoming.getType() == Operation.Type.DELETE && already.getType() == Operation.Type.INSERT) {
            return transformDeleteInsert(incoming, already); // incoming deletes, already inserted
        }
        return transformDeleteDelete(incoming, already); // both are deletes
    }

    private static Operation transformInsertInsert(Operation incoming, Operation already) {
        // If the already-applied insert happened at or before incoming's position,
        // incoming's position shifts right by the length of what was inserted.
        if (already.getPosition() <= incoming.getPosition()) {
            int shifted = incoming.getPosition() + already.getText().length(); // shift past the already-inserted text
            return new Operation(Operation.Type.INSERT, shifted, incoming.getText(), already.getBaseRevision()+1);
        }
        return incoming; // already's insert happened after incoming's position, no shift needed
    }

    private static Operation transformInsertDelete(Operation incoming, Operation already) {
        // A deletion before incoming's position shrinks the document, shifting incoming left.
        if (already.getPosition() < incoming.getPosition()) {
            int shifted = incoming.getPosition() - already.getText().length(); // shrink by the deleted length
            return new Operation(Operation.Type.INSERT, Math.max(shifted, already.getPosition()), incoming.getText(), already.getBaseRevision()+1);
        }
        return incoming; // the deletion happened after incoming's position, no shift needed
    }

    private static Operation transformDeleteInsert(Operation incoming, Operation already) {
        // An insert before incoming's delete position shifts the delete right to still target the same text.
        if (already.getPosition() <= incoming.getPosition()) {
            int shifted = incoming.getPosition() + already.getText().length(); // shift past the newly inserted text
            return new Operation(Operation.Type.DELETE, shifted, incoming.getText(), already.getBaseRevision()+1);
        }
        return incoming; // the insert happened after incoming's delete position, no shift needed
    }

    private static Operation transformDeleteDelete(Operation incoming, Operation already) {
        // If both deletes target the same text, the second one becomes a no-op.
        if (already.getPosition() == incoming.getPosition()) {
            return new Operation(Operation.Type.DELETE, incoming.getPosition(), "", already.getBaseRevision()+1); // no-op, already deleted
        }
        if (already.getPosition() < incoming.getPosition()) {
            int shifted = incoming.getPosition() - already.getText().length(); // shrink by the already-deleted length
            return new Operation(Operation.Type.DELETE, shifted, incoming.getText(), already.getBaseRevision()+1);
        }
        return incoming; // the other deletion happened after incoming's position, no shift needed
    }
}

// The OT server's core loop: apply an incoming operation, transforming it
// against anything committed after the revision it was generated against.
class OTServer {
    private StringBuilder document = new StringBuilder("Hello World"); // starting document content
    private int currentRevision = 0;                                     // how many operations have been committed
    private final List<Operation> committedOperations = new ArrayList<>();  // every operation applied so far, in order

    public synchronized Operation applyOperation(Operation incoming) {
        Operation transformed = incoming; // start from the operation as submitted
        // Transform against every operation committed after the client's base revision.
        for (int i = incoming.getBaseRevision(); i < committedOperations.size(); i++) {
            transformed = OperationalTransform.transform(transformed, committedOperations.get(i)); // fold in each intervening op
        }
        applyToDocument(transformed);           // mutate the live document
        committedOperations.add(transformed);      // record it as committed
        currentRevision++;                            // advance the revision counter
        return transformed; // broadcast this exact transformed operation to every other client
    }

    private void applyToDocument(Operation op) {
        if (op.getType() == Operation.Type.INSERT) {
            document.insert(op.getPosition(), op.getText()); // splice the text in
        } else {
            document.delete(op.getPosition(), op.getPosition() + op.getText().length()); // remove the text
        }
    }

    public String getDocument() { return document.toString(); } // current document content getter
    public int getCurrentRevision() { return currentRevision; }    // current revision getter
}

