        if already.get_position() < incoming.get_position():
            shifted = incoming.get_position() - len(already.get_text())
            return Operation(OperationType.DELETE, shifted, incoming.get_text(), already.get_base_revision() + 1)
        return incoming   # the other deletion happened after incoming's position, no shift needed


